71-424e-99e2-e41e08d259cc"}},{"entry":413,"status":"INSERT","question_id":"bbca480b-b479-4b46-b16a-02bf2ac69454","source":{"entry":413,"stem":"Simplify log₁₀5 + log₁₀6 − log₁₀2.","options":[{"label":"A","text":"log₁₀9","is_correct":false},{"label":"B","text":"log₁₀30","is_correct":false},{"label":"C","text":"log₁₀15","is_correct":true},{"label":"D","text":"log₁₀60","is_correct":false}],"explanation":"Product and quotient rules give log₁₀(5 × 6 ÷ 2) = log₁₀15.","source":"File 2 General, printed question 240","editorial_status":null,"provenance":null,"references":[]},"record":{"entry":413,"stem":"Simplify log₁₀5 + log₁₀6 − log₁₀2.","options":[{"label":"A","text":"log₁₀9","is_correct":false},{"label":"B","text":"log₁₀30","is_correct":false},{"label":"C","text":"log₁₀15","is_correct":true},{"label":"D","text":"log₁₀60","is_correct":false}],"explanation":"Product and quotient rules give log₁₀(5 × 6 ÷ 2) = log₁₀15.","source":"File 2 General, printed question 240","editorial_status":null,"provenance":null,"references":[],"id":"bbca480b-b479-4b46-b16a-02bf2ac69454","subject_id":"36b65a9a-2171-424e-99e2-e41e08d259cc"}},{"entry":414,"status":"INSERT","question_id":"8378e32b-d1fb-47c3-b74b-c0b845ee7496","source":{"entry":414,"stem":"What is the antonym of comfort?","options":[{"label":"A","text":"Ease","is_correct":false},{"label":"B","text":"Relief","is_correct":false},{"label":"C","text":"Pleasure","is_correct":false},{"label":"D","text":"Discomfort","is_correct":true}],"explanation":"Discomfort means a lack of comfort or ease.","source":"File 2 General, printed question 241","editorial_status":null,"provenance":null,"references":[]},"record":{"entry":414,"stem":"What is the antonym of comfort?","options":[{"label":"A","text":"Ease","is_correct":false},{"label":"B","text":"Relief","is_correct":false},{"label":"C","text":"Pleasure","is_correct":false},{"label":"D","text":"Discomfort","is_correct":true}],"explanation":"Discomfort means a lack of comfort or ease.","source":"Fil