 ÷ 27 = 24 days.","source":"File 2 General, printed question 317","editorial_status":null,"provenance":null,"references":[],"id":"fd51fb4c-8be1-4874-b6b6-2565c3de1c6b","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484"}},{"entry":491,"status":"DUPLICATE_SOURCE","question_id":"7c96fd72-9f5d-4df9-9c9d-40e4e2313baf","canonical_entry":19,"source":{"entry":491,"stem":"In which year did Pakistan win the ODI Cricket World Cup?","options":[{"label":"A","text":"1987","is_correct":false},{"label":"B","text":"1996","is_correct":false},{"label":"C","text":"1992","is_correct":true},{"label":"D","text":"1999","is_correct":false}],"explanation":"Pakistan won the 1992 men’s ODI World Cup under Imran Khan.","source":"File 2 General, printed question 318","editorial_status":null,"provenance":null,"references":[]},"record":{"entry":19,"stem":"In which year did Pakistan win the ODI Cricket World Cup?","options":[{"label":"A","text":"1992","is_correct":true},{"label":"B","text":"1987","is_correct":false},{"label":"C","text":"1996","is_correct":false},{"label":"D","text":"1999","is_correct":false}],"explanation":"Pakistan won the 1992 men’s ODI World Cup under Imran Khan.","source":"File 1, printed question 19","editorial_status":null,"provenance":null,"references":[],"id":"7c96fd72-9f5d-4df9-9c9d-40e4e2313baf","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484"}},{"entry":492,"status":"INSERT","question_id":"ec7753e6-a632-4f78-b153-4aaa3c582a27","source":{"entry":492,"stem":"Starting north, a person turns left, left again, then right. Which direction do they face?","options":[{"label":"A","text":"East","is_correct":false},{"label":"B","text":"North","is_correct":false},{"label":"C","text":"South","is_correct":false},{"label":"D","text":"West","is_correct":true}],"explanation":"North → west → south → west gives the final direction.","source":"File 2 General, printed question 319","editorial_status":null,"provenance":null,"references":[]},"record":{"entry":492,"stem":"Starting north, a p