 chloride, NaCl?","options":[{"label":"A","text":"18.02 g/mol","is_correct":false},{"label":"B","text":"98.08 g/mol","is_correct":false},{"label":"C","text":"58.44 g/mol","is_correct":true},{"label":"D","text":"44.01 g/mol","is_correct":false}],"explanation":"Adding sodium’s 22.99 and chlorine’s 35.45 gives approximately 58.44 g/mol.","source":"File 2 Science, printed question 1","editorial_status":null,"provenance":null,"references":[],"id":"5b9c6c45-27c2-4bab-b9af-d58bd2080cc3","subject_id":"a1000000-0000-0000-0000-000000000001"}},{"entry":621,"status":"DUPLICATE_EXISTING","question_id":"805c98bd-0a64-437e-a8fc-1617540b73b3","code":"PN-CADET-A-Q502","source":{"entry":621,"stem":"What is the chemical formula of methane?","options":[{"label":"A","text":"C₂H₆","is_correct":false},{"label":"B","text":"CO₂","is_correct":false},{"label":"C","text":"CH₃OH","is_correct":false},{"label":"D","text":"CH₄","is_correct":true}],"explanation":"Methane has one carbon atom bonded to four hydrogen atoms.","source":"File 2 Science, printed question 2","editorial_status":null,"provenance":null,"references":[]},"record":null},{"entry":622,"status":"INSERT","question_id":"5c80bb3b-e53b-4901-b01d-767e886a9cb1","source":{"entry":622,"stem":"For equal numbers of carbon atoms, what is the ratio of oxygen atoms in CO to CO₂?","options":[{"label":"A","text":"1:2","is_correct":true},{"label":"B","text":"2:1","is_correct":false},{"label":"C","text":"1:1","is_correct":false},{"label":"D","text":"3:2","is_correct":false}],"explanation":"Carbon monoxide has one oxygen per carbon, while carbon dioxide has two.","source":"File 2 Science, printed question 3","editorial_status":null,"provenance":null,"references":[]},"record":{"entry":622,"stem":"For equal numbers of carbon atoms, what is the ratio of oxygen atoms in CO to CO₂?","options":[{"label":"A","text":"1:2","is_correct":true},{"label":"B","text":"2:1","is_correct":false},{"label":"C","text":"1:1","is_correct":false},{"label":"D","text":"3:2",