_correct":true},{"label":"C","text":"58.5 g/mol","is_correct":false},{"label":"D","text":"44 g/mol","is_correct":false}],"explanation":"2(1) + 32 + 4(16) gives approximately 98 g/mol.","source":"File 2 Science, printed question 130","editorial_status":null,"provenance":null,"references":[],"id":"2a461076-4825-452d-ac45-a03b6865bee9","subject_id":"a1000000-0000-0000-0000-000000000001"}}]$attachment$::jsonb) LOOP
